#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto doOp=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np(n);
        // np = p[n-y..n-1] + p[x..n-y-1] + p[0..x-1]
        int idx=0;
        for(int i=n-y;i<n;i++) np[idx++]=p[i];
        for(int i=x;i<n-y;i++) np[idx++]=p[i];
        for(int i=0;i<x;i++) np[idx++]=p[i];
        p=np;
    };
    // Place elements 1..n from left to right
    for(int t=0;t<n-1;t++){
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;
        // Move element at pos to position t
        // Step 1: if pos != n-1, move it to n-1
        if(pos!=n-1){
            // Use op(pos, 1): need pos>0 and pos+1<n i.e. pos<n-1 (true)
            // After: p[n-1], p[pos..n-2], p[0..pos-1]
            // Element was at pos, now it's at... p[pos] is first of middle, goes to index 1
            // Actually let's use: op(1, n-1-pos): element at pos goes to pos-(n-1-pos)+... 
            // Let me just move to end: op with x=pos+1, y= but x+y must be <n
            // Use two steps: first bring to position 0, then to end? 
            // op(1, n-pos): new = p[pos..n-1] + p[1..pos-1] + p[0]. Element at pos goes to index 0.
            if(pos>0 && 1+n-pos<n){
                doOp(1, n-pos);
                pos=0;
            }
        }
        // Now pos is 0 or n-1
        // If pos==0: op(1, n-1-t): new = p[n-1-t..n-1-1] is wrong... let me just compute
        if(pos==0 && t+1<n && 1+(n-1-t)<n){
            doOp(1, n-1-t);
        } else if(pos==n-1 && t+1>0 && t+1<n){
            doOp(t+1, 1);
            // nope, let me recheck
        }
        // recompute if needed
    }
    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
